--
-- Name: tickets_ticket; Type: TABLE; Schema: public; Owner: zaminex
--

CREATE TABLE public.tickets_ticket (
    id bigint NOT NULL,
    ticket_number character varying(32),
    title character varying(255) NOT NULL,
    ticket_type character varying(20) NOT NULL,
    priority character varying(20) NOT NULL,
    status character varying(20) NOT NULL,
    subject_type character varying(20) NOT NULL,
    subject_id bigint NOT NULL,
    tags character varying(40)[] NOT NULL,
    sla_due_at timestamp with time zone,
    closed_at timestamp with time zone,
    reply_count integer NOT NULL,
    last_message_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    closed_by_id bigint,
    created_by_id bigint NOT NULL,
    followup_id bigint,
    last_message_sender_id bigint,
    listing_id bigint,
    property_id bigint,
    related_ticket_id bigint,
    task_id bigint,
    CONSTRAINT ticket_exactly_one_subject CHECK (((((subject_type)::text = 'PROPERTY'::text) AND (property_id IS NOT NULL) AND (listing_id IS NULL) AND (followup_id IS NULL) AND (task_id IS NULL) AND (related_ticket_id IS NULL)) OR (((subject_type)::text = 'LISTING'::text) AND (property_id IS NULL) AND (listing_id IS NOT NULL) AND (followup_id IS NULL) AND (task_id IS NULL) AND (related_ticket_id IS NULL)) OR (((subject_type)::text = 'FOLLOWUP'::text) AND (property_id IS NULL) AND (listing_id IS NULL) AND (followup_id IS NOT NULL) AND (task_id IS NULL) AND (related_ticket_id IS NULL)) OR (((subject_type)::text = 'TASK'::text) AND (property_id IS NULL) AND (listing_id IS NULL) AND (followup_id IS NULL) AND (task_id IS NOT NULL) AND (related_ticket_id IS NULL)) OR (((subject_type)::text = 'TICKET'::text) AND (property_id IS NULL) AND (listing_id IS NULL) AND (followup_id IS NULL) AND (task_id IS NULL) AND (related_ticket_id IS NOT NULL)))),
    CONSTRAINT tickets_ticket_reply_count_check CHECK ((reply_count >= 0)),
    CONSTRAINT tickets_ticket_subject_id_check CHECK ((subject_id >= 0))
);


ALTER TABLE public.tickets_ticket OWNER TO zaminex;

